38	
39	// The fixture's declaration with this mode's installed versions written in: the
40	// engine version at the top, and every declared pack pinned at the same number so
41	// each pack's own records select too. `installed: null` writes nothing, which is the
42	// shape a repo that has never been vendored actually has.
43	function withMode(content, mode) {
44	  const raw = JSON.parse(content);
45	  if (!mode.installed) return content;
46	  const packVersions = {};
47	  for (const entry of raw.packs ?? []) {
48	    const id = typeof entry === 'string' ? entry : entry?.id;
49	    if (typeof id === 'string') packVersions[id] = mode.installed.packVersion;
50	  }
51	  return `${JSON.stringify(withInstalledVersions(raw, { engineVersion: mode.installed.engineVersion, packVersions }), null, 2)}\n`;
52	}
53	
54	export const CANON = dirname(dirname(dirname(fileURLToPath(import.meta.url)))); // vendoring/rehearsal -> canon
55	
