70	export async function buildFixture(fixture, mode) {
71	  const root = mkdtempSync(join(tmpdir(), `claudinite-rehearsal-${fixture.name}-`));
72	  for (const [rel, content] of Object.entries(fixture.files)) {
73	    const abs = join(root, rel);
74	    mkdirSync(dirname(abs), { recursive: true });
75	    // The declaration carries the mode's INSTALLED VERSIONS — that is what selects
76	    // migration records. Written structurally rather than by text substitution: the
77	    // pack versions land one per entry, so there is no single literal to replace,
78	    // and a fixture's declaration is generated data rather than a file anyone reads.
79	    writeFileSync(abs, isSettingsFile(rel) ? withMode(content, mode) : content);
80	  }
81	  // A real repo, because the sweep scopes its file set with git and an
82	  // uninitialised directory makes it fall back to whatever cwd it can find.
83	  //
84	  // `--no-gpg-sign` and the inline identity are not tidiness: a fixture must not
85	  // depend on the HOST's git configuration. A machine with commit signing wired
86	  // up fails these commits for reasons that have nothing to do with the canon
87	  // change under test, and the rehearsal then reports a fleet-breaking result
88	  // because a signing helper was unavailable.
89	  const git = (...a) => execFileAsync('git', [
90	    '-c', 'user.email=rehearsal@example.invalid', '-c', 'user.name=rehearsal',
91	    '-c', 'commit.gpgsign=false', '-c', 'gpg.format=openpgp', ...a,
92	  ], { cwd: root });
93	  await git('init', '-q', '-b', 'main');
94	  await git('commit', '-q', '--allow-empty', '--no-gpg-sign', '-m', 'fixture');
95	  await git('add', '-A');
96	  await git('commit', '-q', '--no-gpg-sign', '-m', 'fixture content');
97	  return root;
98	}
