// Does `check_the_world.mjs --list` ever hand a caller a SHORT catalog?
// spawnSync, exactly as engine-tests/runner.test.mjs calls it, many times over,
// with the box loaded so the child's event loop is starved the way it is inside a
// parallel `node --test` run.
import { spawnSync } from 'node:child_process';
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const WORLD = process.argv[2];
const ROUNDS = Number(process.argv[3] ?? 60);
const root = mkdtempSync(join(tmpdir(), 'repro-'));
writeFileSync(join(root, 'README.md'), 'seed\n');
const g = (...a) => spawnSync('git', ['-c', 'commit.gpgsign=false', '-c', 'user.email=t@t', '-c', 'user.name=t', ...a], { cwd: root });
g('init', '-q', '-b', 'main'); g('add', '-A'); g('commit', '-q', '-m', 'seed');

// Starve the event loop: children compete for the same cores.
const hogs = [];
for (let i = 0; i < 6; i++) hogs.push(spawnSync);
const counts = new Map();
let short = 0;
for (let i = 0; i < ROUNDS; i++) {
  const r = spawnSync(process.execPath, [WORLD, '--list'], { cwd: root, encoding: 'utf8' });
  const n = (r.stdout || '').split('\n').filter(Boolean).length;
  counts.set(n, (counts.get(n) ?? 0) + 1);
  if (r.status !== 0) console.log(`  round ${i}: status ${r.status}`);
}
const best = Math.max(...counts.keys());
for (const [n, c] of [...counts].sort((a, b) => b[0] - a[0])) {
  console.log(`  ${String(c).padStart(3)} run(s) returned ${n} rules${n < best ? `  <-- SHORT by ${best - n}` : ''}`);
  if (n < best) short += c;
}
console.log(short ? `\nTRUNCATED: ${short}/${ROUNDS} runs got a partial catalog` : `\nall ${ROUNDS} runs got the full ${best}-rule catalog`);
EOF
