15:export const SEVERITIES = ['critical', 'high', 'medium', 'low'];
16:export const REASONS = ['correctness', 'performance', 'complexity', 'legal'];
23:export const SIZES = [...SIZE_BOUNDS.map((n) => `<${n}`), `${SIZE_BOUNDS.at(-1)}+`];
25:export function proseSize(words) {
---
export function proseSize(words) {
  const bound = SIZE_BOUNDS.find((n) => words < n);
  return bound ? `<${bound}` : `${SIZE_BOUNDS.at(-1)}+`;
}

